module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic w,
    output logic z
);

    typedef enum logic [2:0] {
        A = 3'd0,
        B = 3'd1,
        C = 3'd2,
        D = 3'd3,
        E = 3'd4,
        F = 3'd5
    } state_t;

    state_t current_state, next_state;

    // State register with synchronous reset
    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= A;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        next_state = current_state;
        case (current_state)
            A: begin
                if (w) next_state = A;
                else   next_state = B;
            end
            B: begin
                if (w) next_state = D;
                else   next_state = C;
            end
            C: begin
                if (w) next_state = D;
                else   next_state = E;
            end
            D: begin
                if (w) next_state = A;
                else   next_state = F;
            end
            E: begin
                if (w) next_state = D;
                else   next_state = E;
            end
            F: begin
                if (w) next_state = D;
                else   next_state = C;
            end
            default: next_state = A;
        endcase
    end

    // Output logic
    always_comb begin
        case (current_state)
            E, F:    z = 1'b1;
            default: z = 1'b0;
        endcase
    end

endmodule

